#import "LegacyCollectors.h"
#import <mach-o/dyld.h>
#import <Foundation/Foundation.h>

static NSString *LegacyKind(const char *image, const char *mainImage) { if(!image||!*image)return @"unknown"; NSString *p=[NSString stringWithUTF8String:image]; if(mainImage&&strcmp(image,mainImage)==0)return @"app"; if([p rangeOfString:@"/System/"].location!=NSNotFound||[p rangeOfString:@"/usr/lib/"].location!=NSNotFound||[p rangeOfString:@"/Developer/"].location!=NSNotFound)return @"system"; if([p rangeOfString:@"/Frameworks/"].location!=NSNotFound)return @"embedded-framework"; return @"unknown"; }
NSUInteger LegacyWriteRuntimeClassIndex(NSURL *jsonlURL, NSURL *textURL, NSURL *summaryURL) { FILE *jf=fopen(jsonlURL.path.UTF8String,"wb"),*tf=fopen(textURL.path.UTF8String,"wb");if(!jf||!tf){if(jf)fclose(jf);if(tf)fclose(tf);return 0;}const char *mainImage=_dyld_get_image_name(0);int n=objc_getClassList(NULL,0);Class *cs=(Class *)malloc(sizeof(Class)*MAX(n,0));n=objc_getClassList(cs,n);NSUInteger total=0,app=0,fw=0,sys=0,unk=0;for(int i=0;i<n;i++){@autoreleasepool{Class c=cs[i];const char *image=class_getImageName(c);NSString *kind=LegacyKind(image,mainImage);if([kind isEqualToString:@"app"])app++;else if([kind isEqualToString:@"embedded-framework"])fw++;else if([kind isEqualToString:@"system"])sys++;else unk++;NSString *name=NSStringFromClass(c)?:@"(anonymous)";NSString *sup=NSStringFromClass(class_getSuperclass(c))?:@"";NSString *path=image?[NSString stringWithUTF8String:image]:@"";NSDictionary *row=@{ @"schemaVersion":@"legacy-1.0", @"class":name, @"superclass":sup, @"image":path, @"imageBasename":path.lastPathComponent?:@"", @"classification":kind, @"detailedMetadata":@NO, @"detailStatus":@"separate-detail-pass" };NSData *jd=[NSJSONSerialization dataWithJSONObject:row options:0 error:nil];if(jd){fwrite(jd.bytes,1,jd.length,jf);fputc('\n',jf);}NSString *line=[NSString stringWithFormat:@"%@ : %@ image=%@ classification=%@\n",name,sup,path.length?path:@"(unknown)",kind];NSData *td=[line dataUsingEncoding:NSUTF8StringEncoding];fwrite(td.bytes,1,td.length,tf);total++;if(total%500==0)fflush(jf),fflush(tf);}}free(cs);fclose(jf);fclose(tf);NSDictionary *summary=@{ @"schemaVersion":@"legacy-1.0", @"complete":@YES, @"completionReason":@"objc_getClassList iteration finished", @"totalClassesEnumerated":@(total), @"appClasses":@(app), @"embeddedFrameworkClasses":@(fw), @"systemClasses":@(sys), @"unknownClasses":@(unk), @"detailPassSeparate":@YES, @"errors":@0, @"truncations":@0 };[[NSJSONSerialization dataWithJSONObject:summary options:NSJSONWritingPrettyPrinted error:nil] writeToURL:summaryURL options:NSDataWritingAtomic error:nil];return total; }
static void LegacyWalk(UIView *v,NSUInteger depth,NSUInteger *nodes,NSUInteger maxDepth,NSUInteger maxNodes,NSHashTable *seen,FILE *f,BOOL *trunc){if(!v||[seen containsObject:v])return;if(depth>maxDepth){*trunc=YES;return;}if(*nodes>=maxNodes){*trunc=YES;return;}[seen addObject:v];(*nodes)++;NSString *line=[NSString stringWithFormat:@"%@%@ %p frame=%@ bounds=%@ hidden=%@ class=%@\n",[[@"" stringByPaddingToLength:depth*2 withString:@" " startingAtIndex:0] description],depth?@"":@"ROOT",v,NSStringFromCGRect(v.frame),NSStringFromCGRect(v.bounds),v.hidden?@"YES":@"NO",NSStringFromClass(v.class)];NSData *d=[line dataUsingEncoding:NSUTF8StringEncoding];fwrite(d.bytes,1,d.length,f);for(UIView *child in [v.subviews copy])LegacyWalk(child,depth+1,nodes,maxDepth,maxNodes,seen,f,trunc);}
NSUInteger LegacyWriteVisibleHierarchy(UIWindow *host, NSURL *url, NSUInteger maxDepth, NSUInteger maxNodes, BOOL *truncated){if(!host||!url)return 0;FILE *f=fopen(url.path.UTF8String,"wb");if(!f)return 0;BOOL trunc=NO;NSUInteger nodes=0;LegacyWalk(host,0,&nodes,maxDepth,maxNodes,[NSHashTable weakObjectsHashTable],f,&trunc);fclose(f);if(truncated)*truncated=trunc;return nodes;}
